    14	            throw new IllegalArgumentException("Authenticated principal is required");
    15	        }
    16	        String username = authentication.getName();
    17	        Set<String> roles = authentication.getAuthorities().stream()
    18	                .map(a -> a.getAuthority())
    19	                .filter(a -> a.startsWith("ROLE_"))
    20	                .map(a -> a.substring(5).toLowerCase(java.util.Locale.ROOT))
    21	                .collect(Collectors.toUnmodifiableSet());
    22	        boolean system = username.equals("system") && roles.contains("system");
