    33	    @Scheduled(fixedDelayString = "${claims.outbox.poll-interval-ms:1000}")
    34	    @Transactional
    35	    public void dispatchDue() {
    36	        List<OutboxRepository.Message> batch = outbox.claimDue(clock.instant(), batchSize);
    37	        for (OutboxRepository.Message message : batch) {
    38	            try {
    39	                delivery.deliver(message);
    40	                if (outbox.markDelivered(message.id(), clock.instant())) {
    41	                    metrics.counter("claims.outbox.delivered", "effect", message.effect()).increment();
    42	                }
    43	            } catch (RuntimeException failure) {
    44	                outbox.markFailed(message.id(), failure.getClass().getSimpleName(), clock.instant().plus(retryDelay));
    45	                metrics.counter("claims.outbox.failed", "effect", message.effect()).increment();
    46	                log.warn("mock_effect_delivery_failed eventId={} effect={} exceptionType={}",
    47	                        message.id(), message.effect(), failure.getClass().getSimpleName());
    48	            }
    49	        }
    50	    }
