124	    @Override
125	    @Transactional
126	    @Auditable(action = "claim.facts.update", resource = "claim")
127	    public Claim updateFacts(UUID claimId, UpdateFactsCommand command, Actor actor, String key, String correlationId) {
128	        requireHuman(actor);
129	        String scope = "claims:" + claimId + ":facts";
130	        String fingerprint = fingerprint(Map.of("expectedVersion", command.expectedVersion(), "facts", command.facts().values()));
131	        lockAndCheckKey(actor, scope, key);
132	        Optional<Claim> replay = replay(actor.id(), scope, key, fingerprint, Claim.class);
133	        if (replay.isPresent()) return replay.get();
134	        ClaimAggregate current = lockedClaim(claimId, actor);
135	        checkVersion(current.claim(), command.expectedVersion());
136	        ClaimFacts merged = mergeFacts(current.claim(), command.facts(), actor);
137	        ClaimWorkflowData data = current.workflow();
138	        if (actor.hasRole("member") && current.claim().state().equals("PENDING_INFO")) {
139	            data = new ClaimWorkflowData(data.informationRequests(), data.lastInformationRequestedAt(), now(),
140	                    data.assessmentStartedAt(), data.rejectedAt(), data.memberAcknowledgedRejectionAt());
141	        }
142	        Claim updated = replace(current.claim(), current.claim().state(), merged, current.claim().version() + 1, now());
143	        if (!claims.compareAndSet(new ClaimAggregate(updated, data), command.expectedVersion())) throw versionConflict();
144	        writeSystemAudit("claim.facts.update", "claim", claimId.toString(), actor, correlationId, "success", null);
145	        storeReceipt(actor.id(), scope, key, fingerprint, updated);
146	        return updated;
147	    }
