153	        requireHuman(actor);
154	        requireRole(actor, "member");
155	        String scope = "claims:" + claimId + ":rejection-acknowledgement";
156	        String fingerprint = fingerprint(Map.of("expectedVersion", expectedVersion, "action", "acknowledge-rejection"));
157	        lockAndCheckKey(actor, scope, key);
158	        Optional<Claim> replay = replay(actor.id(), scope, key, fingerprint, Claim.class);
159	        if (replay.isPresent()) return replay.get();
160	        ClaimAggregate current = lockedClaim(claimId, actor);
161	        checkVersion(current.claim(), expectedVersion);
162	        if (!current.claim().state().equals("REJECTED"))
163	            throw new BusinessException("INVALID_STATE", "Only a rejected claim can be acknowledged", 409);
164	        Instant acknowledgedAt = now();
165	        ClaimWorkflowData old = current.workflow();
166	        ClaimWorkflowData data = new ClaimWorkflowData(old.informationRequests(), old.lastInformationRequestedAt(),
167	                old.lastInformationReceivedAt(), old.assessmentStartedAt(), old.rejectedAt(), acknowledgedAt);
168	        Claim updated = replace(current.claim(), current.claim().state(), current.claim().facts(),
169	                current.claim().version() + 1, acknowledgedAt);
170	        if (!claims.compareAndSet(new ClaimAggregate(updated, data), expectedVersion)) throw versionConflict();
171	        writeSystemAudit("claim.rejection.acknowledge", "claim", claimId.toString(), actor, correlationId, "SUCCESS", null);
172	        storeReceipt(actor.id(), scope, key, fingerprint, updated);
