202	    private TransitionResult doTransition(UUID claimId, TransitionCommand command, Actor actor,
203	            String key, String correlationId, boolean systemCall) {
204	        String scope = "claims:" + claimId + ":transition";
205	        String fingerprint = fingerprint(Map.of("targetState", command.targetState(),
206	                "expectedVersion", command.expectedVersion(), "reason", command.reason(),
207	                "facts", command.suppliedFacts().values(), "system", systemCall));
208	        lockAndCheckKey(actor, scope, key);
209	        Optional<TransitionResult> replay = replay(actor.id(), scope, key, fingerprint, TransitionResult.class);
210	        if (replay.isPresent()) {
211	            TransitionResult result = replay.get();
212	            return new TransitionResult(result.claim(), result.audit(), true);
213	        }
214	        ClaimAggregate current = lockedClaim(claimId, actor);
215	        checkVersion(current.claim(), command.expectedVersion());
216	        ClaimFacts merged = command.suppliedFacts().values().isEmpty()
217	                ? current.claim().facts() : mergeFacts(current.claim(), command.suppliedFacts(), actor);
218	        Claim candidate = replace(current.claim(), current.claim().state(), merged,
219	                current.claim().version(), current.claim().updatedAt());
220	        WorkflowEvidence evidence = evidence(current.workflow(), claimId);
221	        WorkflowDecision decision = workflow.evaluate(new WorkflowEvaluationContext(candidate, actor, command,
222	                evidence, now(), appealPeriod));
223	        if (!decision.allowed()) throw new BusinessException(decision.failureCode(), decision.failureMessage(),
224	                decision.failureCode().equals("ROLE_FORBIDDEN") ? 403 : 409);
225	
226	        Instant occurred = now();
227	        ClaimWorkflowData nextData = updateWorkflowData(current.workflow(), decision, occurred);
228	        ClaimFacts nextFacts = clearStaleAssessmentFacts(merged, decision);
229	        Claim updated = replace(candidate, decision.to(), nextFacts, current.claim().version() + 1, occurred);
230	        if (!claims.compareAndSet(new ClaimAggregate(updated, nextData), command.expectedVersion())) throw versionConflict();
231	
232	        String role = matchingRole(actor, decision.transitionId());
233	        AuditRecord audit = new AuditRecord(UUID.randomUUID(), claimId, updated.version(), occurred,
234	                decision.from(), decision.to(), actor.id(), role, command.reason(), safeCorrelation(correlationId), definition.version());
235	        claimAudit.append(audit);
236	        persistEffects(decision.effects(), claimId, candidate);
237	        writeSystemAudit(systemCall ? "claim.system-transition" : "claim.transition", "claim", claimId.toString(),
238	                actor, correlationId, "success", null);
239	        TransitionResult result = new TransitionResult(updated, audit, false);
240	        storeReceipt(actor.id(), scope, key, fingerprint, result);
241	        return result;
242	    }
