257	    private ClaimWorkflowData updateWorkflowData(ClaimWorkflowData old, WorkflowDecision decision, Instant now) {
258	        int requests = old.informationRequests();
259	        Instant requested = old.lastInformationRequestedAt();
260	        Instant assessment = old.assessmentStartedAt();
261	        Instant rejected = old.rejectedAt();
262	        Instant acknowledged = old.memberAcknowledgedRejectionAt();
263	        for (EffectIntent effect : decision.effects()) {
264	            switch (effect.id()) {
265	                case "record_assessment_start" -> assessment = now;
266	                case "notify_information_request" -> { requests++; requested = now; }
267	                case "reset_assessment_timer" -> assessment = null;
268	                case "notify_member_rejection" -> { rejected = now; acknowledged = null; }
269	                default -> { }
270	            }
271	        }
272	        return new ClaimWorkflowData(requests, requested, old.lastInformationReceivedAt(), assessment, rejected, acknowledged);
273	    }
