291	    private ClaimFacts mergeFacts(Claim current, ClaimFacts patch, Actor actor) {
292	        if (patch.values().isEmpty()) throw invalid("At least one fact must be supplied");
293	        Map<String, Object> merged = new LinkedHashMap<>(current.facts().values());
294	        for (var entry : patch.values().entrySet()) {
295	            String key = entry.getKey();
296	            if (!TOP_LEVEL_FACTS.contains(key)) throw forbidden("Claim fact is not writable: " + key);
297	            if (key.equals("documents")) merged.put(key, mergeDocuments(current, merged.get(key), entry.getValue(), actor));
298	            else if (key.equals("assessorId")) {
299	                if (!actor.hasRole("team_lead") || !Set.of("SUBMITTED", "DOCUMENTS_VERIFIED").contains(current.state()))
300	                    throw forbidden("Only a team lead may assign an assessor before assessment starts");
301	                if (!(entry.getValue() instanceof String s) || s.isBlank()) throw invalid("assessorId must be a nonblank string");
302	                merged.put(key, entry.getValue());
303	            } else {
304	                if (!actor.hasRole("assessor") || !current.state().equals("UNDER_ASSESSMENT")
305	                        || !Objects.equals(actor.id(), current.facts().values().get("assessorId")))
306	                    throw forbidden("Only the assigned assessor may submit an assessment report");
307	                if (!(entry.getValue() instanceof Map<?, ?> report) || !(report.get("complete") instanceof Boolean))
308	                    throw invalid("assessmentReport must contain a boolean complete field");
309	                merged.put(key, entry.getValue());
310	            }
311	        }
312	        return new ClaimFacts(merged);
313	    }
