347	    private static Map<String, Object> mutableMap(Map<?, ?> source) {
348	        Map<String, Object> result = new LinkedHashMap<>();
349	        source.forEach((k, v) -> { if (k instanceof String key) result.put(key, v); });
350	        return result;
351	    }
