377	        IdempotencyRepository.Receipt receipt = idempotency.find(actorId, scope, key).orElse(null);
378	        if (receipt == null) return Optional.empty();
379	        if (!MessageDigest.isEqual(receipt.fingerprint().getBytes(StandardCharsets.US_ASCII), fingerprint.getBytes(StandardCharsets.US_ASCII)))
380	            throw new BusinessException("IDEMPOTENCY_CONFLICT", "Idempotency key was already used for a different request", 409);
381	        try { return Optional.of(json.readValue(receipt.resultJson(), type)); }
