423	    private String matchingRole(Actor actor, String transitionId) {
424	        if (actor.system()) return "system";
425	        return definition.transitions().stream().filter(t -> t.id().equals(transitionId)).findFirst()
426	                .map(t -> t.roles().stream().filter(actor::hasRole).sorted().findFirst().orElse("unknown"))
427	                .orElse("unknown");
