451	        if (!(amount instanceof BigDecimal value) || value.signum() < 0 || value.scale() > 2 || value.precision() - value.scale() > 16)
452	            throw invalid("requestedAmount must be a nonnegative exact decimal fitting NUMERIC(18,2)");
453	    }
