455	    private static final class HexFormatSupport {
456	        private static String sha256(byte[] content) {
457	            try {
458	                byte[] digest = MessageDigest.getInstance("SHA-256").digest(content);
459	                StringBuilder result = new StringBuilder(64);
460	                for (byte b : digest) result.append(Character.forDigit((b >>> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
461	                return result.toString();
462	            } catch (NoSuchAlgorithmException e) { throw new IllegalStateException("SHA-256 is unavailable", e); }
463	        }
464	    }
