 15	/** Records failed mutation attempts in a separate transaction, even when the business transaction rolls back. */
 16	@Service
 17	public class FailureAuditWriter {
 18	    private static final Pattern SAFE_CORRELATION = Pattern.compile("[A-Za-z0-9._:-]{1,128}");
 19	    private final SystemOperationAuditRepository audit;
 20	    private final Clock clock;
 21	    public FailureAuditWriter(SystemOperationAuditRepository audit, Clock clock) { this.audit = audit; this.clock = clock; }
 22	
 23	    @Transactional(propagation = Propagation.REQUIRES_NEW)
 24	    public void record(String action, String resource, String resourceId, Actor actor,
 25	            String correlationId, Throwable failure) {
 26	        if (actor == null) return;
 27	        String errorType = failure instanceof BusinessException business ? business.code() : failure.getClass().getSimpleName();
 28	        String safeCorrelation = correlationId != null && SAFE_CORRELATION.matcher(correlationId).matches()
 29	                ? correlationId : UUID.randomUUID().toString();
 30	        audit.append(new SystemOperationAuditRecord(UUID.randomUUID(), action, resource, resourceId,
 31	                actor.id(), safeCorrelation,
 32	                "FAILED", errorType, clock.instant().truncatedTo(ChronoUnit.MICROS)));
 33	    }
 34	}
