 35	    static final PostgreSQLContainer<?> POSTGRES = new PostgreSQLContainer<>("postgres:16-alpine")
 36	            .withDatabaseName("claims").withUsername("bootstrap").withPassword("bootstrap-test");
 37	    static SqlSessionFactory sessions;
 38	    static final ObjectMapper JSON = new ObjectMapper().enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
 39	
 40	    @org.junit.jupiter.api.BeforeAll
 41	    static void provisionRolesMigrateAndWireProductionMappers() throws Exception {
 42	        try (Connection bootstrap = DriverManager.getConnection(POSTGRES.getJdbcUrl(), POSTGRES.getUsername(), POSTGRES.getPassword());
 43	             Statement sql = bootstrap.createStatement()) {
 44	            sql.execute("CREATE ROLE claims_runtime LOGIN PASSWORD 'runtime-test' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT");
 45	            sql.execute("CREATE ROLE claims_migration LOGIN PASSWORD 'migration-test' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT");
 46	            sql.execute("ALTER SCHEMA public OWNER TO claims_migration");
 47	            sql.execute("GRANT CONNECT ON DATABASE claims TO claims_migration, claims_runtime");
 48	            sql.execute("GRANT USAGE, CREATE ON SCHEMA public TO claims_migration");
 49	        }
 50	        try (Connection migration = DriverManager.getConnection(POSTGRES.getJdbcUrl(), "claims_migration", "migration-test")) {
 51	            var database = DatabaseFactory.getInstance().findCorrectDatabaseImplementation(new JdbcConnection(migration));
 52	            try (Liquibase liquibase = new Liquibase("db/changelog/db.changelog-master.yml", new ClassLoaderResourceAccessor(), database)) {
 53	                liquibase.update(new Contexts(), new LabelExpression());
 54	            }
 55	            try (Connection verification = DriverManager.getConnection(POSTGRES.getJdbcUrl(), "claims_migration", "migration-test");
 56	                 Statement check = verification.createStatement();
 57	                 var result = check.executeQuery("SELECT current_user, nspname, pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='public'")) {
 58	                assertThat(result.next()).isTrue();
 59	                assertThat(result.getString(1)).isEqualTo("claims_migration");
 60	                assertThat(result.getString(3)).isEqualTo("claims_migration");
 61	            }
 62	        }
 63	        SqlSessionFactoryBean factory = new SqlSessionFactoryBean();
 64	        factory.setDataSource(runtimeDataSource());
 65	        factory.setMapperLocations(new PathMatchingResourcePatternResolver().getResources("classpath:sql/service/claim/*.xml"));
 66	        sessions = factory.getObject();
 67	    }
 68	
 69	    static DataSource runtimeDataSource() {
 70	        var source = new DriverManagerDataSource(POSTGRES.getJdbcUrl(), "claims_runtime", "runtime-test");
 71	        source.setDriverClassName("org.postgresql.Driver");
 72	        return source;
 73	    }
 74	    static Connection runtime() throws SQLException {
 75	        return DriverManager.getConnection(POSTGRES.getJdbcUrl(), "claims_runtime", "runtime-test");
 76	    }
 77	    static SqlSession session() { return sessions.openSession(true); }
 78	    static ClaimMapper claims(SqlSession s) { return s.getMapper(ClaimMapper.class); }
 79	    static AuditMapper audits(SqlSession s) { return s.getMapper(AuditMapper.class); }
 80	    static ReceiptMapper receipts(SqlSession s) { return s.getMapper(ReceiptMapper.class); }
 81	    static EffectsMapper effects(SqlSession s) { return s.getMapper(EffectsMapper.class); }
 82	    static MyBatisClaimRepository claimRepository(SqlSession s) { return new MyBatisClaimRepository(claims(s), JSON); }
 83	    static MyBatisClaimAuditRepository auditRepository(SqlSession s) { return new MyBatisClaimAuditRepository(audits(s)); }
 84	    static MyBatisIdempotencyRepository idempotencyRepository(SqlSession s) { return new MyBatisIdempotencyRepository(receipts(s), JSON); }
 85	    static MyBatisPaymentRepository paymentRepository(SqlSession s) { return new MyBatisPaymentRepository(effects(s)); }
 86	    static MyBatisOutboxRepository outboxRepository(SqlSession s, long leaseMillis) { return new MyBatisOutboxRepository(effects(s), leaseMillis); }
 87	    static UUID rawClaim() throws SQLException {
 88	        UUID id = UUID.randomUUID();
 89	        try (var c = runtime(); var p = c.prepareStatement("INSERT INTO claims(id,member_id,state,policy_limit,currency) VALUES(?, 'member-1','submitted',125.00,'USD')")) {
 90	            p.setObject(1,id); p.executeUpdate();
 91	        }
 92	        return id;
 93	    }
 94	}
