 15	    @Test
 16	    void migrationOwnsSchemaAndRuntimeCannotCreateObjects() throws Exception {
 17	        try (var c=runtime(); var s=c.createStatement(); var r=s.executeQuery("SELECT rolname,rolsuper,rolcreatedb,rolcreaterole FROM pg_roles WHERE rolname IN ('claims_migration','claims_runtime') ORDER BY rolname")) {
 18	            assertThat(r.next()).isTrue(); assertThat(r.getString(1)).isEqualTo("claims_migration");
 19	            assertThat(r.getBoolean(2)).isFalse(); assertThat(r.getBoolean(3)).isFalse(); assertThat(r.getBoolean(4)).isFalse();
 20	            assertThat(r.next()).isTrue(); assertThat(r.getString(1)).isEqualTo("claims_runtime");
 21	            assertThat(r.getBoolean(2)).isFalse(); assertThat(r.getBoolean(3)).isFalse(); assertThat(r.getBoolean(4)).isFalse(); assertThat(r.next()).isFalse();
 22	        }
 23	        try (var c=runtime(); var s=c.createStatement(); var r=s.executeQuery("SELECT has_schema_privilege('claims_migration','public','CREATE'),has_schema_privilege('claims_runtime','public','USAGE'),has_schema_privilege('claims_runtime','public','CREATE')")) {
 24	            assertThat(r.next()).isTrue(); assertThat(r.getBoolean(1)).isTrue(); assertThat(r.getBoolean(2)).isTrue(); assertThat(r.getBoolean(3)).isFalse();
 25	        }
 26	        try (var c=runtime(); var s=c.createStatement(); var r=s.executeQuery("SELECT has_column_privilege('claims_runtime','claims','member_id','UPDATE'),has_column_privilege('claims_runtime','claims','policy_limit','UPDATE'),has_column_privilege('claims_runtime','claims','currency','UPDATE'),has_column_privilege('claims_runtime','claims','state','UPDATE')")) {
 27	            assertThat(r.next()).isTrue(); assertThat(r.getBoolean(1)).isFalse(); assertThat(r.getBoolean(2)).isFalse(); assertThat(r.getBoolean(3)).isFalse(); assertThat(r.getBoolean(4)).isTrue();
 28	        }
 29	        try (var c=runtime(); var s=c.createStatement()) {
 30	            assertThat(catchThrowable(() -> s.execute("CREATE TABLE runtime_must_not_create(id integer)"))).isNotNull();
 31	        }
 32	    }
