 34	    @Test
 35	    void repositoryRoundTripListsAndCasLeaveImmutableIdentityAndCoverageUntouched() {
 36	        UUID id=UUID.randomUUID(); Instant now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);
 37	        BigDecimal nested=new BigDecimal("42.375");
 38	        ClaimAggregate original=new ClaimAggregate(new Claim(id,"member-1","submitted",new BigDecimal("125.00"),"USD",0,
 39	                new ClaimFacts(Map.of("nested",Map.of("amount",nested))),now,now),ClaimWorkflowData.empty());
 40	        try (var s=session()) {
 41	            var repo=claimRepository(s); repo.insert(original);
 42	            ClaimAggregate found=repo.find(id).orElseThrow();
 43	            assertThat(found.claim().facts().values().get("nested")).isInstanceOf(Map.class);
 44	            Object actual=((Map<?,?>)found.claim().facts().values().get("nested")).get("amount");
 45	            assertThat(actual).isInstanceOf(BigDecimal.class).isEqualTo(nested);
 46	            assertThat(found.claim().memberId()).isEqualTo("member-1");
 47	            assertThat(found.claim().policyLimit()).isEqualByComparingTo("125.00");
 48	            assertThat(found.claim().currency()).isEqualTo("USD");
 49	            assertThat(repo.listVisible(new PageRequest(0,10),new Actor("member-1",Set.of("member"),false)).items()).extracting(a->a.claim().id()).contains(id);
 50	            ClaimAggregate attempted=new ClaimAggregate(new Claim(id,"attacker","assessing",new BigDecimal("1.00"),"EUR",0,
 51	                    new ClaimFacts(Map.of("changed",true)),now,now),ClaimWorkflowData.empty());
 52	            assertThat(repo.compareAndSet(attempted,0)).isTrue();
 53	            Claim unchanged=repo.find(id).orElseThrow().claim();
 54	            assertThat(unchanged.state()).isEqualTo("assessing");
 55	            assertThat(unchanged.memberId()).isEqualTo("member-1");
 56	            assertThat(unchanged.policyLimit()).isEqualByComparingTo("125.00");
 57	            assertThat(unchanged.currency()).isEqualTo("USD");
 58	            assertThat(repo.compareAndSet(attempted,0)).isFalse();
 59	        }
 60	    }
